<?php
namespace App\Services\AI;
use App\Contracts\AIProviderInterface;use App\Models\AISuggestion;use App\Models\BankTransaction;use App\Services\Audit\AuditService;
final class TransactionAIService {public function __construct(private AIProviderInterface $provider,private StructuredTransactionSchema $schema,private AuditService $audit){}
 public function suggest(BankTransaction $tx):AISuggestion{$payload=['description_raw'=>$tx->description_raw,'reference'=>$tx->reference,'amount'=>(float)$tx->amount,'currency'=>$tx->currency,'direction'=>is_object($tx->direction)?$tx->direction->value:$tx->direction,'booking_date'=>optional($tx->booking_date)->format('Y-m-d')];$validated=$this->schema->validate($this->provider->analyzeTransaction($payload,$this->schema->definition()));$s=AISuggestion::create(['organization_id'=>$tx->organization_id,'entity_type'=>BankTransaction::class,'entity_id'=>$tx->id,'provider'=>config('ai.default','heuristic'),'model'=>config('ai.providers.heuristic.model','rules-v1'),'schema_version'=>StructuredTransactionSchema::VERSION,'response'=>$validated,'confidence'=>$validated['confidence']*100,'status'=>'proposed']);$this->audit->record('ai.suggestion.created',$s,null,$s->toArray(),['bank_transaction_id'=>$tx->id]);return $s;}}
